CREATE TRIGGER IF NOT EXISTS v272_task_protocol_conformance_run_projection
BEFORE INSERT ON compute_external_pool_adapter_task_protocol_conformance_run_receipts
WHEN NEW.run_receipt_schema IS NOT json_extract(NEW.run_receipt_json,'$.schema')
 OR NEW.run_receipt_id IS NOT json_extract(NEW.run_receipt_json,'$.run_receipt_id')
 OR NEW.run_receipt_digest IS NOT json_extract(NEW.run_receipt_json,'$.run_receipt_digest')
 OR NEW.run_material_digest IS NOT json_extract(NEW.run_receipt_json,'$.run_material_digest')
 OR NEW.canonicalization IS NOT json_extract(NEW.run_receipt_json,'$.canonicalization')
 OR NEW.digest_algorithm IS NOT json_extract(NEW.run_receipt_json,'$.digest_algorithm')
 OR NEW.registry_release_id IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.registry_release_id')
 OR NEW.registry_release_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.registry_release_digest')
 OR NEW.registry_release_material_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.registry_release_material_digest')
 OR NEW.admission_id IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.admission_id')
