 OR NEW.package_material_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.package_material_digest')
 OR NEW.source_receipt_id IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.source_receipt_id')
 OR NEW.source_receipt_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.source_receipt_digest')
 OR NEW.adapter_id IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.adapter_id')
 OR NEW.release_version IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.release_version')
 OR NEW.route_kind IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.route_kind')
 OR NEW.implementation_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.implementation_digest')
