 OR NEW.installation_content_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.installation_content_digest')
 OR NEW.capability_set_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.registry_release.capability_set_digest')
 OR NEW.vulnerability_reattestation_receipt_id IS NOT json_extract(NEW.run_receipt_json,'$.run.vulnerability_reattestation.reattestation_receipt_id')
 OR NEW.vulnerability_reattestation_receipt_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.vulnerability_reattestation.reattestation_receipt_digest')
 OR NEW.vulnerability_reattestation_material_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.vulnerability_reattestation.reattestation_material_digest')
