 OR NEW.sandbox_reattestation_material_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.sandbox_reattestation.reattestation_material_digest')
 OR NEW.sandbox_policy_id IS NOT json_extract(NEW.run_receipt_json,'$.run.sandbox_reattestation.sandbox_policy_id')
 OR NEW.sandbox_test_plan_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.sandbox_reattestation.test_plan_digest')
 OR NEW.sandbox_observation_inventory_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.sandbox_reattestation.observation_inventory_digest')
