 OR NEW.sandbox_verifier_key_record_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.sandbox_verifier_key.key_record_digest')
 OR NEW.sandbox_verifier_key_id IS NOT json_extract(NEW.run_receipt_json,'$.run.sandbox_verifier_key.key_id')
 OR NEW.sandbox_verifier_operator IS NOT json_extract(NEW.run_receipt_json,'$.run.sandbox_verifier_key.verifier_operator')
 OR NEW.sandbox_verifier_product IS NOT json_extract(NEW.run_receipt_json,'$.run.sandbox_verifier_key.verifier_product')
 OR NEW.runtime_compatibility_verification_receipt_id IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.verification_receipt_id')
 OR NEW.runtime_compatibility_verification_receipt_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.verification_receipt_digest')
 OR NEW.runtime_compatibility_verification_material_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.verification_material_digest')
 OR NEW.runtime_compatibility_run_observation_id IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.run_observation_id')
 OR NEW.runtime_compatibility_run_observation_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.run_observation_digest')
 OR NEW.runtime_compatibility_run_observation_material_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.run_observation_material_digest')
 OR NEW.runtime_compatibility_runner_execution_id IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.runner_execution_id')
 OR NEW.runtime_compatibility_profile_id IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.profile_id')
 OR NEW.runtime_compatibility_profile_revision IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.profile_revision')
 OR NEW.runtime_compatibility_profile_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.profile_digest')
 OR NEW.runtime_compatibility_runner_policy_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.runner_policy_digest')
