 OR NEW.supervisor_session_policy_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.supervisor_session_policy_digest')
 OR NEW.source_capsule_sha256 IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.source_capsule_sha256')
 OR NEW.source_capsule_size_bytes IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.source_capsule_size_bytes')
 OR NEW.launch_image_sha256 IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.launch_image_sha256')
 OR NEW.launch_image_size_bytes IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.launch_image_size_bytes')
 OR NEW.runtime_compatibility_public_fixture_delivery_root IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.public_fixture_delivery_root')
 OR NEW.runtime_compatibility_expires_at IS NOT json_extract(NEW.run_receipt_json,'$.run.runtime_compatibility.expires_at')
 OR NEW.task_protocol_profile_id IS NOT json_extract(NEW.run_receipt_json,'$.run.task_protocol_profile_id')
 OR NEW.task_protocol_profile_revision IS NOT json_extract(NEW.run_receipt_json,'$.run.task_protocol_profile_revision')
 OR NEW.task_protocol_profile_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.task_protocol_profile_digest')
 OR NEW.fixture_catalog_id IS NOT json_extract(NEW.run_receipt_json,'$.run.fixture_catalog_id')
 OR NEW.fixture_catalog_revision IS NOT json_extract(NEW.run_receipt_json,'$.run.fixture_catalog_revision')
 OR NEW.fixture_catalog_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.fixture_catalog_digest')
 OR NEW.run_nonce_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.run_nonce_digest')
 OR NEW.public_fixture_delivery_root IS NOT json_extract(NEW.run_receipt_json,'$.run.public_fixture_delivery_root')
 OR json(NEW.session_root_digests_json) IS NOT json(json_extract(NEW.run_receipt_json,'$.run.session_root_digests'))
 OR NEW.session_roots_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.session_roots_digest')
 OR NEW.session_transcript_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.session_transcript_digest')
 OR NEW.delivery_inventory_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.delivery_inventory_digest')
 OR NEW.exchange_inventory_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.exchange_inventory_digest')
 OR NEW.task_observation_root IS NOT json_extract(NEW.run_receipt_json,'$.run.task_observation_root')
 OR NEW.synthetic_fixture_lane_id IS NOT json_extract(NEW.run_receipt_json,'$.run.synthetic_subjects.fixture_lane.subject_id')
 OR NEW.synthetic_fixture_lane_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.synthetic_subjects.fixture_lane.subject_digest')
 OR NEW.synthetic_fixture_executor_id IS NOT json_extract(NEW.run_receipt_json,'$.run.synthetic_subjects.fixture_executor.subject_id')
 OR NEW.synthetic_fixture_executor_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.synthetic_subjects.fixture_executor.subject_digest')
 OR NEW.exchange_count IS NOT json_array_length(json_extract(NEW.run_receipt_json,'$.run.exchanges'))
 OR NEW.capability_count IS NOT json_array_length(json_extract(NEW.run_receipt_json,'$.run.capabilities'))
 OR NEW.duration_ms IS NOT json_extract(NEW.run_receipt_json,'$.run.duration_ms')
 OR json(NEW.cleanup_json) IS NOT json(json_extract(NEW.run_receipt_json,'$.run.cleanup'))
 OR NEW.sequence IS NOT json_extract(NEW.run_receipt_json,'$.run.sequence')
 OR NEW.predecessor_run_receipt_id IS NOT json_extract(NEW.run_receipt_json,'$.run.predecessor_run_receipt_id')
 OR NEW.predecessor_run_receipt_digest IS NOT json_extract(NEW.run_receipt_json,'$.run.predecessor_run_receipt_digest')
 OR NEW.run_started_at IS NOT json_extract(NEW.run_receipt_json,'$.run.run_started_at')
 OR NEW.run_completed_at IS NOT json_extract(NEW.run_receipt_json,'$.run.run_completed_at')
 OR NEW.post_cleanup_checked_at IS NOT json_extract(NEW.run_receipt_json,'$.run.post_cleanup_checked_at')
 OR NEW.expires_at IS NOT json_extract(NEW.run_receipt_json,'$.run.expires_at')
 OR NEW.recorded_at IS NOT json_extract(NEW.run_receipt_json,'$.run.recorded_at')
 OR NEW.evidence_scope IS NOT json_extract(NEW.run_receipt_json,'$.run.evidence_scope')
 OR NEW.receipt_status IS NOT json_extract(NEW.run_receipt_json,'$.run.receipt_status')
 OR NEW.non_production_authority_status IS NOT json_extract(NEW.run_receipt_json,'$.run.non_production_authority_status')
 OR json(NEW.effects_json) IS NOT json(json_extract(NEW.run_receipt_json,'$.run.effects'))
 OR json(NEW.readiness_json) IS NOT json(json_extract(NEW.run_receipt_json,'$.run.readiness'))
BEGIN SELECT RAISE(ABORT,'V272 task protocol run scalar projection mismatch'); END;

CREATE TRIGGER IF NOT EXISTS v272_task_protocol_conformance_revocation_projection
BEFORE INSERT ON compute_external_pool_adapter_task_protocol_conformance_revocations
WHEN NEW.revocation_receipt_schema IS NOT json_extract(NEW.revocation_receipt_json,'$.schema')
 OR NEW.revocation_receipt_id IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation_receipt_id')
 OR NEW.revocation_receipt_digest IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation_receipt_digest')
 OR NEW.revocation_material_digest IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation_material_digest')
 OR NEW.canonicalization IS NOT json_extract(NEW.revocation_receipt_json,'$.canonicalization')
 OR NEW.digest_algorithm IS NOT json_extract(NEW.revocation_receipt_json,'$.digest_algorithm')
 OR NEW.run_receipt_id IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.run_receipt_id')
 OR NEW.run_receipt_digest IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.run_receipt_digest')
 OR NEW.registry_release_id IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.registry_release_id')
 OR NEW.registry_release_digest IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.registry_release_digest')
 OR NEW.reason IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.reason')
 OR NEW.revoked_at IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.revoked_at')
 OR NEW.recorded_at IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.recorded_at')
 OR NEW.revocation_status IS NOT json_extract(NEW.revocation_receipt_json,'$.revocation.revocation_status')
 OR json(NEW.effects_json) IS NOT json(json_extract(NEW.revocation_receipt_json,'$.revocation.effects'))
 OR json(NEW.readiness_json) IS NOT json(json_extract(NEW.revocation_receipt_json,'$.revocation.readiness'))
BEGIN SELECT RAISE(ABORT,'V272 task protocol revocation scalar projection mismatch'); END;
